+  subtract: (a, b) => a - b,
+  multiply: (a, b) => a * b,
+  divide: (a, b) => a / b,
+};
+
+const REQUIRED = ['a', 'b', 'operation'];
+
+function isFiniteNumber(value) {
+  return typeof value === 'number' && Number.isFinite(value);
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'calculate',
+      description: 'Perform a basic arithmetic calculation on two numbers.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          a: { type: 'number', description: 'The first operand.' },
+          b: { type: 'number', description: 'The second operand.' },
+          operation: {
+            type: 'string',
+            enum: ['add', 'subtract', 'multiply', 'divide'],
+            description: 'The arithmetic operation to perform.',
+          },
+        },
+        required: REQUIRED,
+        additionalProperties: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args) {
+  if (name !== 'calculate') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object');
+  }
+
+  const extras = Object.keys(args).filter((key) => !REQUIRED.includes(key));
+  if (extras.length > 0) {
+    throw new Error(`Unexpected arguments: ${extras.join(', ')}`);
+  }
+
+  for (const field of REQUIRED) {
+    if (!(field in args)) {
+      throw new Error(`Missing required argument: ${field}`);
+    }
+  }
+
+  const { a, b, operation } = args;
+
+  if (!isFiniteNumber(a)) {
+    throw new Error('Argument "a" must be a finite number');
+  }
+  if (!isFiniteNumber(b)) {
+    throw new Error('Argument "b" must be a finite number');
+  }
+  if (!Object.prototype.hasOwnProperty.call(OPERATIONS, operation)) {
+    throw new Error(`Unsupported operation: ${operation}`);
+  }
+  if (operation === 'divide' && b === 0) {
+    throw new Error('Division by zero');
+  }
+
+  const result = OPERATIONS[operation](a, b);
+
+  return {
+    content: [{ type: 'text', text: String(result) }],
+  };
+}
